import java.util.ArrayList;
import java.util.List;

class FoodChain {

    private static final String[] ANIMALS = {
        "fly", "spider", "bird", "cat", "dog", "goat", "cow", "horse"
    };

    private static final String[] COMMENTS = {
        "",
        "It wriggled and jiggled and tickled inside her.",
        "How absurd to swallow a bird!",
        "Imagine that, to swallow a cat!",
        "What a hog, to swallow a dog!",
        "Just opened her throat and swallowed a goat!",
        "I don't know how she swallowed a cow!",
        "She's dead, of course!"
    };

    String verse(int verse) {
        int index = verse - 1;
        String animal = ANIMALS[index];

        List<String> lines = new ArrayList<>();
        lines.add("I know an old lady who swallowed a " + animal + ".");

        if (!COMMENTS[index].isEmpty()) {
            lines.add(COMMENTS[index]);
        }

        for (int i = index; i >= 1; i--) {
            String prey = ANIMALS[i - 1];
            String suffix = prey.equals("spider")
                ? " that wriggled and jiggled and tickled inside her"
                : "";
            lines.add("She swallowed the " + ANIMALS[i] + " to catch the " + prey + suffix + ".");
        }

        if (index < ANIMALS.length - 1) {
            lines.add("I don't know why she swallowed the fly. Perhaps she'll die.");
        }

        return String.join("\n", lines);
    }

    String verses(int startVerse, int endVerse) {
        StringBuilder song = new StringBuilder();
        for (int verse = startVerse; verse <= endVerse; verse++) {
            if (verse > startVerse) {
                song.append("\n");
            }
            song.append(verse(verse));
        }
        return song.toString();
    }

}

